import{_ as a,o as i,c as t,a2 as r}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Tinkering","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/professions/tinkering.md","filePath":"en/guide/professions/tinkering.md"}'),n={name:"en/guide/professions/tinkering.md"};function s(o,e,d,l,c,h){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="tinkering" tabindex="-1">Tinkering <a class="header-anchor" href="#tinkering" aria-label="Permalink to &quot;Tinkering&quot;">​</a></h1><p><strong>Status:</strong> Proposed · Not established as playable.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><ul><li>Understand and build precision mechanisms with clear limits.</li><li>Diagnosis, repair, traps and security create expedition roles.</li><li>Automation and constructs are future directions, not unlimited factories.</li></ul><p><span id="at-a-glance"></span><span id="what-it-does"></span><span id="why-take-it-into-the-field"></span><span id="learning-and-specialization"></span><span id="future-directions-and-limits"></span></p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Activity</th><th>What you do</th></tr></thead><tbody><tr><td>Work on a device</td><td>Inspect, design, assemble, calibrate, test and maintain.</td></tr><tr><td>Learn from the world</td><td>Record clues in a Mechanist’s Journal; reverse engineering can damage the device.</td></tr><tr><td>Support the group</td><td>Diagnose traps, repair machinery or help restore a lift or bridge.</td></tr></tbody></table><h2 id="compared-with-classic-uo" tabindex="-1">Compared with classic UO <a class="header-anchor" href="#compared-with-classic-uo" aria-label="Permalink to &quot;Compared with classic UO&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Classic UO</th><th>Syrolands direction</th></tr></thead><tbody><tr><td>Tinkers already make tools, components and useful devices.</td><td>Diagnosis, calibration and reverse engineering become deeper activities.</td></tr><tr><td>Later UO also includes mechanical pets.</td><td>Future constructs would fit a broader, bounded mechanism system; details remain open.</td></tr></tbody></table><p>Comparison uses familiar UO crafting loops; the official references also cover later expansions. <a href="https://uo.com/wiki/ultima-online-wiki/skills/tinkering/" target="_blank" rel="noreferrer">Tinkering</a>.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><p>A tinkerer could diagnose a broken lift during an expedition. Understanding the mechanism may reveal a repair approach instead of treating every device as a recipe.</p><h2 id="progression-and-trade-offs" tabindex="-1">Progression and trade-offs <a class="header-anchor" href="#progression-and-trade-offs" aria-label="Permalink to &quot;Progression and trade-offs&quot;">​</a></h2><ul><li>Tinkering understands and builds locks; Lockpicking defeats them. Security and burglary need counterplay, with no trivial total house loss.</li><li>Alchemical payloads, gates, alarms and feeders are candidates. Automation limits and advanced golems remain undecided.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><p><a href="/Syrolands-Public/en/guide/professions/alchemy.html">Alchemy</a> · <a href="/Syrolands-Public/en/guide/professions/blacksmithing.html">Blacksmithing</a> · <a href="/Syrolands-Public/en/guide/professions/carpentry.html">Carpentry</a> · <a href="/Syrolands-Public/en/guide/characters/familiarity.html">Familiarity practice</a> · <a href="/Syrolands-Public/en/guide/professions/overview.html">Profession System</a></p><h2 id="full-design-specification" tabindex="-1">Full design specification <a class="header-anchor" href="#full-design-specification" aria-label="Permalink to &quot;Full design specification&quot;">​</a></h2><p><a href="/Syrolands-Public/en/game-design/professions/tinkering.html">Tinkering</a></p>',18)])])}const m=a(n,[["render",s]]);export{u as __pageData,m as default};
